        this.openedBy = openedBy;
    }
}
'''
open(p,'w').write(s)
p='java/net/officefloor/hq/app/claim/ClaimService.java'
s=open(p).read()
s=s.replace('''        Person person = requirePerson(sheetId, claim.getPersonId());
        claim.setStatus(next);
        if (next == ClaimStatus.OPEN) {
            claim.setNumber(number);
        }''','''        // Four eyes: whoever opened a claim cannot also settle it.
        if (next == ClaimStatus.SETTLED && user.equals(claim.getOpenedBy())) {
            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "The user who opened a claim cannot settle it.");
        }
        Person person = requirePerson(sheetId, claim.getPersonId());
        claim.setStatus(next);
        if (next == ClaimStatus.OPEN) {
            claim.setNumber(number);
            claim.setOpenedBy(user);
        }''')
open(p,'w').write(s)
p='java/net/officefloor/hq/app/claim/ClaimController.java'
s=open(p).read()
s=s.replace('''     * until it is settled. */
    public record ClaimView(Long id, Long personId, String amount, LocalDate date, String note, ClaimStatus status,
            Integer number, String due) {''','''     * until it is settled; it shows who opened it, if anyone did. */
    public record ClaimView(Long id, Long personId, String amount, LocalDate date, String note, ClaimStatus status,
            Integer number, String due, String openedBy) {''')
