                    claim.getOpenedBy());''')
open(p,'w').write(s)
p='frontend/src/app/features/claims/claims-api.ts'
s=open(p).read()
s=s.replace('''  due: string | null;
}''','''  due: string | null;
  /** Who opened the claim; null while it is a draft. */
  openedBy: string | null;
}''',1)
open(p,'w').write(s)
p='frontend/src/app/features/claims/claims.ts'
s=open(p).read()
s=s.replace('''            <th scope="col">Status</th>''','''            <th scope="col">Status</th>
            <th scope="col">Opened by</th>''')
s=s.replace('''              <td data-testid="claim-status">{{ c.status }}</td>''','''              <td data-testid="claim-status">{{ c.status }}</td>
              <td data-testid="claim-opened-by">{{ c.openedBy ?? '' }}</td>''')
s=s.replace('''            e.status === 409''','''            e.status === 403
              ? 'You opened that claim, so someone else must settle it.'
              : e.status === 409''')
open(p,'w').write(s)
EOF
